{
  "packet_id": "H6-T01-3",
  "claim_id": "C060",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C060.component",
    "value": "When too few comparable bookings leave inadequate evidence, trial success or failure should not be claimed.",
    "scope": "An evidential limit under inadequate comparable-booking coverage, not a claim that the trial has succeeded or failed.",
    "provenance": {
      "refs": [
        {
          "source_id": "P035",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P035 explicitly supplies the condition of inadequate evidence from too few comparable bookings and the restriction on declaring success or failure."
    }
  },
  "signal_basis": {
    "component_id": "C060.signal_basis",
    "value": "Prospective trial observations and comparison with comparable baseline bookings yield too few comparable bookings to provide adequate evidence for a success or failure judgment.",
    "scope": "Trial evaluation accounting for equipment, crew and demand differences; the relevant signal is inadequate comparable-booking coverage.",
    "provenance": {
      "refs": [
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P035",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans specify prospective outcome observation, qualified baseline comparison, and the condition of insufficient comparable bookings."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C060.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is SUPPORTED, not CONDITIONAL_WARRANT."
    }
  },
  "rationale": "Given the stipulated inadequacy of the comparative evidence, withholding a success or failure conclusion is warranted. The claim does not infer either outcome from sparse observations or require an additional empirical relation.",
  "uncertainty": "No numerical adequacy threshold is supplied, but the claim expressly applies only when the available evidence is inadequate; it does not classify any particular booking count.",
  "anomalies": []
}
